import { useCallback, useRef, useEffect } from 'react';
import { useClassFramework } from '../contexts/ClassFrameworkContext';
import { ElementClass, TooltipPosition } from '../types/ClassFramework';

interface UseClassElementOptions {
  elementId: string;
  classId: string;
  position?: 'top' | 'bottom' | 'left' | 'right';
  trigger?: 'hover' | 'click' | 'both';
  customNote?: Partial<ElementClass['customNote']>;
}

export function useClassElement({
  elementId,
  classId,
  position = 'top',
  trigger = 'hover',
  customNote,
}: UseClassElementOptions) {
  const { attachClass, detachClass, showTooltip, hideTooltip, getClassesForElement } = useClassFramework();
  const elementRef = useRef<HTMLDivElement>(null);
  const timeoutRef = useRef<NodeJS.Timeout | null>(null);
  const longPressTimeoutRef = useRef<NodeJS.Timeout | null>(null);
  const isLongPressRef = useRef<boolean>(false);

  // Attach class to element on mount
  useEffect(() => {
    attachClass({
      elementId,
      classId,
      position,
      trigger,
      customNote,
    });

    return () => {
      detachClass(elementId, classId);
    };
  }, [elementId, classId, position, trigger, customNote, attachClass, detachClass]);

  const handleMouseEnter = useCallback(() => {
    if (trigger === 'click' || !elementRef.current) return;

    // Clear any existing timeout
    if (timeoutRef.current) {
      clearTimeout(timeoutRef.current);
      timeoutRef.current = null;
    }

    // Show tooltip after a small delay
    timeoutRef.current = setTimeout(() => {
      if (elementRef.current) {
        const rect = elementRef.current.getBoundingClientRect();
        const position: TooltipPosition = {
          x: rect.left + rect.width / 2,
          y: rect.top - 10,
          element: elementRef.current,
        };
        showTooltip(elementId, position, classId);
      }
    }, 300);
  }, [trigger, elementId, classId, showTooltip]);

  const handleMouseLeave = useCallback(() => {
    if (trigger === 'click') return;

    if (timeoutRef.current) {
      clearTimeout(timeoutRef.current);
      timeoutRef.current = null;
    }

    // Hide tooltip after a small delay
    timeoutRef.current = setTimeout(() => {
      hideTooltip();
    }, 200);
  }, [trigger, hideTooltip]);

  const handleClick = useCallback(() => {
    if (trigger === 'hover' || !elementRef.current) return;

    // On mobile, only show tooltip if it was a long press
    const isMobile = window.innerWidth <= 768 || 'ontouchstart' in window;
    console.log('Click handler called - isMobile:', isMobile, 'isLongPress:', isLongPressRef.current);

    if (isMobile && !isLongPressRef.current) {
      console.log('Blocking click on mobile - not a long press');
      showDebugIndicator('Click blocked - use long press!');
      return;
    }

    const rect = elementRef.current.getBoundingClientRect();
    const position: TooltipPosition = {
      x: rect.left + rect.width / 2,
      y: rect.top - 10,
      element: elementRef.current,
    };
    console.log('Showing tooltip via click handler');
    showTooltip(elementId, position, classId);
  }, [trigger, elementId, classId, showTooltip]);

  const handleTouchStart = useCallback(() => {
    if (trigger === 'hover' || !elementRef.current) return;

    // Start long press timer
    isLongPressRef.current = false;
    longPressTimeoutRef.current = setTimeout(() => {
      isLongPressRef.current = true;

      // Check if mobile and center the tooltip
      const isMobile = window.innerWidth <= 768 || 'ontouchstart' in window;
      let position: TooltipPosition;

      if (isMobile) {
        // Center on screen for mobile
        position = {
          x: window.innerWidth / 2,
          y: window.innerHeight / 2,
          element: elementRef.current!,
        };
      } else {
        // Use element position for desktop
        const rect = elementRef.current!.getBoundingClientRect();
        position = {
          x: rect.left + rect.width / 2,
          y: rect.top - 10,
          element: elementRef.current!,
        };
      }

      console.log('Long press detected - showing tooltip for mobile:', isMobile);
      showTooltip(elementId, position, classId);

      // Show visual debug indicator
      if (isMobile) {
        showDebugIndicator('Long press detected!');
      }

      // Reset long press state after showing tooltip
      setTimeout(() => {
        isLongPressRef.current = false;
      }, 100);
    }, 500); // 500ms for long press
  }, [trigger, elementId, classId, showTooltip]);

  // Visual debug indicator function
  const showDebugIndicator = (message: string) => {
    const indicator = document.createElement('div');
    indicator.style.cssText = `
      position: fixed;
      top: 20px;
      left: 50%;
      transform: translateX(-50%);
      background: red;
      color: white;
      padding: 10px 20px;
      border-radius: 5px;
      z-index: 100000;
      font-size: 16px;
      font-weight: bold;
    `;
    indicator.textContent = message;
    document.body.appendChild(indicator);

    setTimeout(() => {
      document.body.removeChild(indicator);
    }, 2000);
  };

  const handleTouchEnd = useCallback(() => {
    if (trigger === 'hover') return;

    // Clear long press timer
    if (longPressTimeoutRef.current) {
      clearTimeout(longPressTimeoutRef.current);
      longPressTimeoutRef.current = null;
    }

    // On mobile, only hide if it wasn't a long press
    const isMobile = window.innerWidth <= 768;
    if (isMobile && !isLongPressRef.current) {
      hideTooltip();
    }
  }, [trigger, hideTooltip]);

  const handleTouchMove = useCallback(() => {
    if (trigger === 'hover') return;

    // Cancel long press if user moves finger
    if (longPressTimeoutRef.current) {
      clearTimeout(longPressTimeoutRef.current);
      longPressTimeoutRef.current = null;
    }
  }, [trigger]);

  // Cleanup timeout on unmount
  useEffect(() => {
    return () => {
      if (timeoutRef.current) {
        clearTimeout(timeoutRef.current);
      }
      if (longPressTimeoutRef.current) {
        clearTimeout(longPressTimeoutRef.current);
      }
    };
  }, []);

  const getEventHandlers = () => {
    const handlers: Record<string, any> = {};
    const isMobile = window.innerWidth <= 768 || 'ontouchstart' in window;

    if (trigger === 'hover' || trigger === 'both') {
      handlers.onMouseEnter = handleMouseEnter;
      handlers.onMouseLeave = handleMouseLeave;
    }

    if (trigger === 'click' || trigger === 'both') {
      // Only add click handler on desktop
      if (!isMobile) {
        handlers.onClick = handleClick;
      }
      // Always add touch handlers
      handlers.onTouchStart = handleTouchStart;
      handlers.onTouchEnd = handleTouchEnd;
      handlers.onTouchMove = handleTouchMove;

      // Add visual indicator for mobile
      if (isMobile) {
        handlers.style = { cursor: 'pointer' };
        handlers.title = 'Long press for info';
      }
    }

    return handlers;
  };

  const hasClass = getClassesForElement(elementId).some(ec => ec.classId === classId);

  return {
    ref: elementRef,
    eventHandlers: getEventHandlers(),
    hasClass,
    elementClasses: getClassesForElement(elementId),
  };
}
